python -c "
import toolz
from toolz.functoolz import should_curry

for name in ['apply', 'compose_left', 'compose', 'comp', 'pipe', 'identity', 'thread_first', 'thread_last', 'curry', 'peek', 'peekn', 'get_config_from_root']:
    func = getattr(toolz, name, None)
    if func is None:
        print(f'{name}: NOT FOUND')
    else:
        print(f'{name}: should_curry={should_curry(func)}, type={type(func).__name__}')

print()
# Also check what happens with the curried check
for name in ['apply', 'compose_left', 'compose', 'comp', 'pipe', 'identity', 'thread_first', 'thread_last', 'curry', 'peek', 'peekn', 'get_config_from_root']:
    func = getattr(toolz, name, None)
    if func is not None:
        nargs = toolz.functoolz.num_required_args(func)
        has_kw = toolz.functoolz.has_keywords(func)
        print(f'{name}: nargs={nargs}, has_keywords={has_kw}')
"
